  items: [{ id: '1', name: 'Protection Services', price: 99.99 }],
  total: 99.99,
  clearCart: vi.fn()
};

const mockPayment = {
  processPayment: vi.fn()
};

vi.mock('./CartContext', () => ({ useCart: () => mockCart }));
vi.mock('./PaymentContext', () => ({ usePayment: () => mockPayment }));

describe('Checkout - We are a franchise operation. We have standards.', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockCart.items = [{ id: '1', name: 'Protection Services', price: 99.99 }];
