      await user.type(screen.getByLabelText(/name on card/i), 'Uncle Enzo');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Act - Review & Place Order
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-2024-001')).toBeInTheDocument();
      expect(mockCart.clearCart).toHaveBeenCalled();
    });
  });

  describe('Form Validation', () => {
    it('displays shipping validation errors for empty fields', async () => {
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });

